package integrity

// فحوصات المخازن والمركبات (11-04). قراءة بس. الشروط من الكود:
// الطلعة: IN_PROGRESS ← COMPLETED ويا endedAt والعدّاد (vehicle_mission_repository.EndMission)،
// طلب الأداة: APPROVED ويا approvedAt، RETURNED ويا returnedAt (inventory_repository)،
// طلب الشراء: FULFILLED ويا fulfilledAt و totalCost (procurement_repository).

func init() {
	Checks = append(Checks,
		Check{Key: "vehicle_multiple_active_missions", Domain: "ops", Severity: "high",
			Title:  "سيارة بيها أكثر من طلعة شغّالة",
			Why:    "النظام يقرا طلعة وحدة شغّالة للسيارة — الثانية تضل مفتوحة للأبد والمسافة والسائق يتلخبطون.",
			Fix:    "نسد الطلعة القديمة بعدّادها.",
			Count:  `SELECT count(*)::bigint n FROM (SELECT "vehicleId" FROM "VehicleMission" WHERE status = 'IN_PROGRESS' GROUP BY 1 HAVING count(*) > 1) t`,
			Sample: `SELECT v.id, v.name||' ('||COALESCE(v."plateNumber",'-')||') طلعات شغّالة × '||count(*) info FROM "VehicleMission" m JOIN "Vehicle" v ON v.id = m."vehicleId" WHERE m.status = 'IN_PROGRESS' GROUP BY v.id, v.name, v."plateNumber" HAVING count(*) > 1 LIMIT 20`},
		Check{Key: "vehicle_mission_stuck", Domain: "ops", Severity: "medium",
			Title:  "طلعات سيارة مفتوحة أكثر من يومين",
			Why:    "السائق نسى يسد الطلعة — السيارة تبين مشغولة والمسافة ما تنحسب.",
			Fix:    "نسد الطلعة بعدّاد السيارة الحالي ونبلّغ السائق.",
			Count:  `SELECT count(*)::bigint n FROM "VehicleMission" WHERE status = 'IN_PROGRESS' AND "startedAt" < now() - interval '2 days'`,
			Sample: `SELECT m.id, v.name||' — '||COALESCE(e.name,'?')||' من '||(m."startedAt"::date)::text info FROM "VehicleMission" m JOIN "Vehicle" v ON v.id = m."vehicleId" LEFT JOIN "Employee" e ON e.id = m."driverId" WHERE m.status = 'IN_PROGRESS' AND m."startedAt" < now() - interval '2 days' ORDER BY m."startedAt" LIMIT 20`},
		Check{Key: "vehicle_mission_bad_odometer", Domain: "ops", Severity: "medium",
			Title:  "طلعات مسافتها سالبة أو خيالية",
			Why:    "العدّاد بالنهاية أقل من البداية أو فرق أكثر من ٢٠٠٠ كم بطلعة — المسافة والوقود والصيانة تنحسب غلط.",
			Fix:    "نصحّح العدّاد من صورة لوحة السيارة.",
			Count:  `SELECT count(*)::bigint n FROM "VehicleMission" WHERE status = 'COMPLETED' AND "endOdometer" IS NOT NULL AND ("endOdometer" < "startOdometer" OR "endOdometer" - "startOdometer" > 2000)`,
			Sample: `SELECT m.id, v.name||' '||m."startOdometer"||' → '||m."endOdometer"||' ('||(m."startedAt"::date)::text||')' info FROM "VehicleMission" m JOIN "Vehicle" v ON v.id = m."vehicleId" WHERE m.status = 'COMPLETED' AND m."endOdometer" IS NOT NULL AND (m."endOdometer" < m."startOdometer" OR m."endOdometer" - m."startOdometer" > 2000) LIMIT 20`},
		Check{Key: "vehicle_odometer_behind_missions", Domain: "ops", Severity: "low",
			Title:  "عدّاد السيارة أقل من آخر طلعة",
			Why:    "سد الطلعة يحدّث عدّاد السيارة — أقل من آخر طلعة يعني تعديل يدوي غلط، والطلعة الجاية تبدي من رقم غلط.",
			Fix:    "نرجّع عدّاد السيارة لآخر قراءة طلعة.",
			Count:  `SELECT count(*)::bigint n FROM "Vehicle" v WHERE v."currentOdometer" < (SELECT max(m."endOdometer") FROM "VehicleMission" m WHERE m."vehicleId" = v.id)`,
			Sample: `SELECT v.id, v.name||' العدّاد '||v."currentOdometer"||' وآخر طلعة '||(SELECT max(m."endOdometer") FROM "VehicleMission" m WHERE m."vehicleId" = v.id) info FROM "Vehicle" v WHERE v."currentOdometer" < (SELECT max(m."endOdometer") FROM "VehicleMission" m WHERE m."vehicleId" = v.id) LIMIT 20`},
		Check{Key: "vehicle_document_expired", Domain: "ops", Severity: "medium",
			Title:  "سيارة شغّالة ومستمسكها منتهي",
			Why:    "آخر نسخة من المستمسك (سنوية، تأمين…) منتهية — السيارة تطلع بالشارع بلا أوراق.",
			Fix:    "نجدد المستمسك ونرفع النسخة الجديدة.",
			Count:  `SELECT count(*)::bigint n FROM (SELECT DISTINCT ON (d."vehicleId", d."documentType") d."expiryDate" FROM "VehicleDocument" d JOIN "Vehicle" v ON v.id = d."vehicleId" WHERE v."isActive" AND d."expiryDate" IS NOT NULL ORDER BY d."vehicleId", d."documentType", d."expiryDate" DESC) t WHERE t."expiryDate" < now()`,
			Sample: `SELECT t."vehicleId" id, t.name||' — '||t."documentType"||' انتهى '||(t."expiryDate"::date)::text info FROM (SELECT DISTINCT ON (d."vehicleId", d."documentType") d."vehicleId", v.name, d."documentType", d."expiryDate" FROM "VehicleDocument" d JOIN "Vehicle" v ON v.id = d."vehicleId" WHERE v."isActive" AND d."expiryDate" IS NOT NULL ORDER BY d."vehicleId", d."documentType", d."expiryDate" DESC) t WHERE t."expiryDate" < now() LIMIT 20`},
		Check{Key: "driver_license_expired_authorized", Domain: "ops", Severity: "high",
			Title:  "سائق مخوّل وإجازته منتهية",
			Why:    "النظام يخليه يطلع بالسيارة وإجازة السوق منتهية — مسؤولية قانونية على الشركة.",
			Fix:    "نوقف التخويل لحد ما يجدد الإجازة.",
			Count:  `SELECT count(*)::bigint n FROM "VehicleDriver" d JOIN "Employee" e ON e.id = d."employeeId" WHERE d.authorized AND e.status::text = 'ACTIVE' AND d."licenseExpiry" < current_date`,
			Sample: `SELECT e.id, e.name||' — الإجازة انتهت '||d."licenseExpiry"::text info FROM "VehicleDriver" d JOIN "Employee" e ON e.id = d."employeeId" WHERE d.authorized AND e.status::text = 'ACTIVE' AND d."licenseExpiry" < current_date LIMIT 20`},
		Check{Key: "tool_request_missing_dates", Domain: "ops", Severity: "medium",
			Title:  "طلبات أدوات بحالة بلا تاريخها",
			Why:    "الموافقة تعبّي approvedAt والإرجاع يعبّي returnedAt — بلاهن مدة بقاء الأداة عند الموظف ما تنحسب.",
			Fix:    "نعبّي التاريخ من سجل التدقيق.",
			Count:  `SELECT count(*)::bigint n FROM "ToolRequest" WHERE (status::text = 'APPROVED' AND "approvedAt" IS NULL) OR (status::text = 'RETURNED' AND "returnedAt" IS NULL) OR (status::text = 'REJECTED' AND "rejectedAt" IS NULL)`,
			Sample: `SELECT r.id, COALESCE(e.name,'?')||' '||r.status::text||' طُلب '||(r."requestedAt"::date)::text info FROM "ToolRequest" r LEFT JOIN "Employee" e ON e.id = r."employeeId" WHERE (r.status::text = 'APPROVED' AND r."approvedAt" IS NULL) OR (r.status::text = 'RETURNED' AND r."returnedAt" IS NULL) OR (r.status::text = 'REJECTED' AND r."rejectedAt" IS NULL) LIMIT 20`},
		Check{Key: "tool_held_by_inactive_employee", Domain: "ops", Severity: "high",
			Title:  "أدوات عند موظف مو فعّال",
			Why:    "طلب أداة موافق عليه وما رجع، والموظف طلع — الأداة تضيع من المخزن.",
			Fix:    "نسترجع الأداة أو نسجّلها مفقودة.",
			Count:  `SELECT count(*)::bigint n FROM "ToolRequest" r JOIN "Employee" e ON e.id = r."employeeId" WHERE r.status::text = 'APPROVED' AND e.status::text <> 'ACTIVE'`,
			Sample: `SELECT r.id, e.name||' ('||e.status::text||') — '||COALESCE(r.description, r."toolId", '?') info FROM "ToolRequest" r JOIN "Employee" e ON e.id = r."employeeId" WHERE r.status::text = 'APPROVED' AND e.status::text <> 'ACTIVE' LIMIT 20`},
		Check{Key: "procurement_fulfilled_incomplete", Domain: "ops", Severity: "high",
			Title:  "طلبات شراء منفّذة بلا كلفة أو تاريخ",
			Why:    "مجموع المصروف على المشتريات ينحسب من totalCost للمنفّذة — بلا كلفة الرقم ينقص، وبلا تاريخ ما تدخل بالشهر.",
			Fix:    "نعبّي الكلفة من الوصل وتاريخ التنفيذ.",
			Count:  `SELECT count(*)::bigint n FROM "ProcurementRequest" WHERE status::text = 'FULFILLED' AND ("fulfilledAt" IS NULL OR "totalCost" IS NULL OR "totalCost" <= 0)`,
			Sample: `SELECT id, COALESCE(code,'?')||' كلفة='||COALESCE("totalCost"::text,'-')||' تاريخ='||COALESCE(("fulfilledAt"::date)::text,'-') info FROM "ProcurementRequest" WHERE status::text = 'FULFILLED' AND ("fulfilledAt" IS NULL OR "totalCost" IS NULL OR "totalCost" <= 0) LIMIT 20`},
		Check{Key: "material_negative_stock", Domain: "ops", Severity: "medium",
			Title:  "مواد مخزونها بالسالب",
			Why:    "انصرف أكثر من الموجود — يعني إدخال ناقص أو صرف مكرر، والجرد يطلع كذب.",
			Fix:    "نسوي جرد للمادة ونصحّح الكمية.",
			Count:  `SELECT count(*)::bigint n FROM "Material" WHERE "stockQty" < 0`,
			Sample: `SELECT id, name||' ('||COALESCE(code,'-')||') = '||"stockQty"::text info FROM "Material" WHERE "stockQty" < 0 ORDER BY "stockQty" LIMIT 20`},
	)
}
